def find_solutions(max_p, max_q):
    solutions = []
    for q in range(1, max_q + 1):
        for p in range(-max_p, max_p + 1):
            if p == 0:
                solutions.append((0, 0))
                continue
            if p == 2 * q:
                continue

            val = p * (p**2 - 2*p*q - q**2) * (p - 2*q)
            if val >= 0:
                root = int(val**0.5)
                if root * root == val:
                    a = p / q
                    b_sq = (a**3 - 2*a**2 - a) / (a - 2)
                    # Since b^2 = val / (q^2 * (p - 2q)), we know it's a square
                    # because val = k^2 and q^2 is a square and (p-2q) is a factor of val
                    # wait, b_sq = val / (q^2 * (p-2q))
                    # actually b_sq = p(p^2 - 2pq - q^2) / (q^2(p-2q))
                    # if p(p^2 - 2pq - q^2)(p-2q) = k^2, then
                    # b_sq = k^2 / (q^2(p-2q)^2)
                    # so b = k / (q * (p-2q))
                    b = root / (q * (p - 2*q))
                    solutions.append((a, b))
    return list(set(solutions))

