                continue
            num = p**4 - 8*p**3*q + 18*p**2*q**2 + 8*p*q**3 + q**4
            if num >= 0:
                root = int(num**0.5)
                if root * root == num:
                    u = p/q
                    D = u**4 - 8*u**3 + 18*u**2 + 8*u + 1
                    # D should be a square.
                    # If root^2 == num, then D = (root/q^2)^2.
                    # root_D = root / q^2
                    root_D = root / (q**2)
                    a1 = (4*u + u**2 + 1 + root_D) / (4*u)
