def find_points():
    solutions = []
    for q in range(1, 21):
        for p in range(-20, 21):
            if p == 0: continue
            t = Fraction(p, q)
            v2 = -2*t**3 + 3*t**2 + 4*t + 1
            if v2 >= 0:
                # Check if v2 is a square of a rational
                # v2 = num / den
                num = v2.numerator
                den = v2.denominator
                if num >= 0 and num**2 % (num * den) == 0: # This is wrong
                    pass
                # Let's just use a simple check
                sqrt_v2 = v2**0.5
                if abs(sqrt_v2 - round(sqrt_v2)) < 1e-9:
                    solutions.append((t, round(sqrt_v2)))
                elif abs(sqrt_v2 - Fraction(round(sqrt_v2), 1)) < 1e-9:
                    pass
                else:
                    # Check if it's a rational square
                    # v2 = n / d. We need n*d to be a square.
                    if num * den == (int((num * den)**0.5))**2:
                        solutions.append((t, Fraction(int((num * den)**0.5), den)))
    return sorted(list(set(solutions)))

